package com.sixthdegree;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.http.api.RuneLiteAPI;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Singleton
final class SixthDegreeApiClient
{
	static final String API_BASE = "https://amnesty-bootlace-poach.ngrok-free.dev/runelite/v1";
	private static final MediaType PNG = MediaType.get("image/png");

	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	SixthDegreeApiClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	CompletableFuture<AuthStart> startDiscordAuth(String rsn)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("rsn", rsn);
		Request request = baseRequest(API_BASE + "/auth/session")
			.post(RequestBody.create(RuneLiteAPI.JSON, gson.toJson(payload)))
			.build();
		return sendJson(request, AuthStart.class);
	}

	CompletableFuture<AuthStatus> getDiscordAuthStatus(String requestId)
	{
		Request request = baseRequest(API_BASE + "/auth/status/" + requestId).get().build();
		return sendJson(request, AuthStatus.class);
	}

	CompletableFuture<MemberStatus> getMemberStatus(String sessionToken)
	{
		return getAuthed("/me", sessionToken, MemberStatus.class);
	}

	CompletableFuture<Dashboard> getDashboard(String sessionToken)
	{
		return getAuthed("/dashboard", sessionToken, Dashboard.class);
	}

	CompletableFuture<CompetitionResponse> getCompetition(String kind, String sessionToken)
	{
		return getAuthed("/competitions/" + kind + "/state", sessionToken, CompetitionResponse.class);
	}

	CompletableFuture<CompetitionProgressResponse> postCompetitionProgress(
		String kind,
		String sessionToken,
		int eventId,
		long delta,
		long currentValue,
		long observedAt,
		String telemetryId)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("event_id", eventId);
		payload.addProperty("delta", delta);
		payload.addProperty("current_value", currentValue);
		payload.addProperty("observed_at", observedAt);
		payload.addProperty("telemetry_id", telemetryId);
		Request request = authedRequest(API_BASE + "/competitions/" + kind + "/progress", sessionToken)
			.post(RequestBody.create(RuneLiteAPI.JSON, gson.toJson(payload)))
			.build();
		return sendJson(request, CompetitionProgressResponse.class);
	}

	CompletableFuture<LfgResponse> getLfg(String sessionToken)
	{
		return getAuthed("/lfg", sessionToken, LfgResponse.class);
	}

	CompletableFuture<LfgPostResponse> postLfg(String sessionToken, String note, int world)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("note", note);
		payload.addProperty("world", world);
		Request request = authedRequest(API_BASE + "/lfg", sessionToken)
			.post(RequestBody.create(RuneLiteAPI.JSON, gson.toJson(payload)))
			.build();
		return sendJson(request, LfgPostResponse.class);
	}

	CompletableFuture<BasicResponse> deleteMyLfg(String sessionToken)
	{
		Request request = authedRequest(API_BASE + "/lfg/me", sessionToken).delete().build();
		return sendJson(request, BasicResponse.class);
	}

	CompletableFuture<NotificationResponse> getNotificationRules(String sessionToken)
	{
		return getAuthed("/notifications", sessionToken, NotificationResponse.class);
	}

	CompletableFuture<String> getNpcDropRarityData(String sessionToken)
	{
		Request request = authedRequest(API_BASE + "/rarity/npc-drops", sessionToken).get().build();
		return sendText(request);
	}

	CompletableFuture<NotificationPostResponse> postNotification(
		String sessionToken,
		SixthDegreeNotificationEvent event,
		byte[] screenshotPng)
	{
		MultipartBody.Builder body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("event_id", safe(event.eventId))
			.addFormDataPart("type", safe(event.type))
			.addFormDataPart("title", safe(event.title))
			.addFormDataPart("detail", safe(event.detail))
			.addFormDataPart("source", safe(event.source))
			.addFormDataPart("value_gp", Long.toString(event.valueGp))
			.addFormDataPart("occurred_at", Long.toString(event.occurredAt))
			.addFormDataPart("item_id", Integer.toString(event.itemId))
			.addFormDataPart("rarity_triggered", Boolean.toString(event.rarityTriggered));

		if (screenshotPng != null && screenshotPng.length > 0)
		{
			body.addFormDataPart(
				"image",
				"sixth-degree.png",
				RequestBody.create(PNG, screenshotPng));
		}

		Request request = authedRequest(API_BASE + "/notifications/submit", sessionToken)
			.post(body.build())
			.build();
		return sendJson(request, NotificationPostResponse.class);
	}

	CompletableFuture<LootBatchResponse> postLootBatch(
		String sessionToken,
		String batchId,
		long valueGp,
		int dropCount,
		long recordedAt)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("batch_id", batchId);
		payload.addProperty("value_gp", valueGp);
		payload.addProperty("drop_count", dropCount);
		payload.addProperty("recorded_at", recordedAt);
		Request request = authedRequest(API_BASE + "/telemetry/loot-batch", sessionToken)
			.post(RequestBody.create(RuneLiteAPI.JSON, gson.toJson(payload)))
			.build();
		return sendJson(request, LootBatchResponse.class);
	}

	CompletableFuture<LootLeaderboardResponse> getLootLeaderboard(String period, String sessionToken)
	{
		return getAuthed("/leaderboards/loot?period=" + period, sessionToken, LootLeaderboardResponse.class);
	}

	private <T> CompletableFuture<T> getAuthed(String path, String token, Class<T> type)
	{
		Request request = authedRequest(API_BASE + path, token).get().build();
		return sendJson(request, type);
	}

	private Request.Builder authedRequest(String url, String token)
	{
		return baseRequest(url).header("Authorization", "Bearer " + token);
	}

	private Request.Builder baseRequest(String url)
	{
		return new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.header("User-Agent", "Sixth-Degree-RuneLite/0.1.8")
			.header("ngrok-skip-browser-warning", "sixth-degree-runelite");
	}

	private <T> CompletableFuture<T> sendJson(Request request, Class<T> type)
	{
		CompletableFuture<T> future = new CompletableFuture<>();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					String body = responseText(response);
					ensureSuccess(response.code(), body);
					future.complete(gson.fromJson(body, type));
				}
				catch (Exception e)
				{
					future.completeExceptionally(e);
				}
			}
		});
		return future;
	}

	private CompletableFuture<String> sendText(Request request)
	{
		CompletableFuture<String> future = new CompletableFuture<>();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					String body = responseText(response);
					ensureSuccess(response.code(), body);
					future.complete(body);
				}
				catch (Exception e)
				{
					future.completeExceptionally(e);
				}
			}
		});
		return future;
	}

	private static String responseText(Response response) throws IOException
	{
		ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	private void ensureSuccess(int status, String body)
	{
		if (status >= 200 && status < 300)
		{
			return;
		}
		String reason = defaultReason(status);
		try
		{
			JsonObject error = gson.fromJson(body, JsonObject.class);
			if (error != null)
			{
				if (error.has("reason"))
				{
					reason = error.get("reason").getAsString();
				}
				else if (error.has("error"))
				{
					reason = error.get("error").getAsString() + " (HTTP " + status + ")";
				}
			}
		}
		catch (Exception ignored)
		{
			// Keep the status-based message for non-JSON proxy responses.
		}
		throw new ApiException(status, reason);
	}

	private static String safe(String value)
	{
		return value == null ? "" : value;
	}

	private static String defaultReason(int status)
	{
		if (status == 404)
		{
			return "Boss Lady is missing the latest RuneLite content API (HTTP 404). Run BotSync/update and restart the bot.";
		}
		if (status == 401 || status == 403)
		{
			return "RuneLite access needs to be revalidated (HTTP " + status + ").";
		}
		return "Sixth Degree API returned HTTP " + status + ".";
	}

	static final class ApiException extends RuntimeException
	{
		private final int statusCode;

		ApiException(int statusCode, String message)
		{
			super(message);
			this.statusCode = statusCode;
		}

		int getStatusCode()
		{
			return statusCode;
		}
	}

	static final class BasicResponse
	{
		boolean ok;
	}

	static final class AuthStart
	{
		String request_id;
		String authorize_url;
		int expires_in;
	}

	static final class AuthStatus
	{
		String status;
		String session_token;
		String discord_user_id;
		String rsn;
		String reason;
	}

	static final class MemberStatus
	{
		boolean ok;
		String access;
		String rsn;
		String discord_user_id;
		boolean clan_member_role;
		int role_recheck_seconds;
	}

	static final class Dashboard
	{
		boolean ok;
		long server_time;
		String rsn;
		String announcement;
		EventItem[] events;
		CompetitionResponse botw;
		CompetitionResponse sotw;
		int lfg_count;
		int standings_refresh_seconds;
	}

	static final class EventItem
	{
		int id;
		String title;
		String description;
		long start_time;
		long end_time;
		int attending_count;
		String event_type;
		int world;
		String location;
		String requirements;
		boolean live;
	}

	static final class CompetitionResponse
	{
		boolean ok;
		String type;
		Competition active;
		RecentCompetition[] recent;
	}

	static final class Competition
	{
		int id;
		int event_id;
		String title;
		String description;
		String metric;
		long start_time;
		long end_time;
		String prize;
		String status;
		boolean paused;
		boolean live;
		boolean reconcile_allowed;
		Standing[] standings;
		Standing you;
	}

	static final class RecentCompetition
	{
		int id;
		String title;
		String metric;
		long start_time;
		long end_time;
		String prize;
		String status;
	}

	static final class Standing
	{
		int rank;
		String rsn;
		long baseline;
		long current_value;
		long score;
		long updated_at;
	}

	static final class CompetitionProgressResponse
	{
		boolean ok;
		boolean accepted;
		boolean paused;
		Standing standing;
	}

	static final class LfgResponse
	{
		boolean ok;
		LfgEntry[] entries;
		int ttl_seconds;
	}

	static final class LfgPostResponse
	{
		boolean ok;
		LfgEntry entry;
	}

	static final class LfgEntry
	{
		String rsn;
		String note;
		int world;
		long created_at;
		long expires_at;
	}

	static final class NotificationResponse
	{
		boolean ok;
		JsonObject rules;
		String[] member_controls;
	}

	static final class NotificationPostResponse
	{
		boolean ok;
		boolean posted;
		boolean duplicate;
	}

	static final class LootBatchResponse
	{
		boolean ok;
		boolean accepted;
	}

	static final class LootLeaderboardResponse
	{
		boolean ok;
		String period;
		long since;
		long server_time;
		long round_display_to_gp;
		LootLeaderboardEntry[] entries;
		LootLeaderboardEntry you;
	}

	static final class LootLeaderboardEntry
	{
		int rank;
		String rsn;
		long value_gp;
		long drop_count;
		long updated_at;
	}
}

package com.sixthdegree;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Locale;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
final class SixthDegreeCompetitionTracker
{
	private static final long STATE_REFRESH_SECONDS = 30L;
	private static final long MAX_BOTW_DELTA = 10_000L;
	private static final long MAX_SOTW_DELTA = 500_000_000L;
	private static final Pattern BOSS_COUNT = Pattern.compile(
		"Your (.+?)\\s(?:kill|chest|completion|harvest|success|opened)\\s?count is: ?([\\d,]+)\\b",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern BOSS_COUNT_SECONDARY = Pattern.compile(
		"Your (?:completed|subdued) (.+?) count is: ([\\d,]+)\\b",
		Pattern.CASE_INSENSITIVE);

	private static final Pattern RIFTS_CLOSED = Pattern.compile(
		"^Amount of rifts you have closed: ([0-9][0-9,]*)\\.$", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final ClientThread clientThread;
	private final SixthDegreeApiClient apiClient;
	private final SixthDegreeSoundService sounds;
	private final SixthDegreeConfig config;
	private final CompetitionContext botw = new CompetitionContext("BOTW");
	private final CompetitionContext sotw = new CompetitionContext("SOTW");
	private final AtomicBoolean botwRefreshInFlight = new AtomicBoolean(false);
	private final AtomicBoolean sotwRefreshInFlight = new AtomicBoolean(false);

	private ScheduledExecutorService scheduler;
	private volatile String sessionToken;
	private volatile boolean active;

	@Inject
	SixthDegreeCompetitionTracker(
		Client client,
		ClientThread clientThread,
		SixthDegreeApiClient apiClient,
		SixthDegreeSoundService sounds,
		SixthDegreeConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.apiClient = apiClient;
		this.sounds = sounds;
		this.config = config;
	}

	SixthDegreeCompetitionTracker(Client client, ClientThread clientThread, SixthDegreeApiClient apiClient)
	{
		this(client, clientThread, apiClient, null, null);
	}

	void start()
	{
		if (scheduler != null && !scheduler.isShutdown())
		{
			return;
		}
		scheduler = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread thread = new Thread(r, "sixth-degree-competitions");
			thread.setDaemon(true);
			return thread;
		});
		scheduler.scheduleAtFixedRate(
			this::refreshState,
			STATE_REFRESH_SECONDS,
			STATE_REFRESH_SECONDS,
			TimeUnit.SECONDS);
	}

	void stop()
	{
		deactivate();
		if (scheduler != null)
		{
			scheduler.shutdownNow();
			scheduler = null;
		}
	}

	void activate(String token)
	{
		if (token == null || token.isBlank())
		{
			return;
		}
		boolean changed = !active || !token.equals(sessionToken);
		sessionToken = token;
		active = true;
		if (changed)
		{
			clientThread.invokeLater(() ->
			{
				botw.reset();
				botw.resetSoundObservation();
				sotw.reset();
				sotw.resetSoundObservation();
			});
		}
		refreshState();
	}

	void deactivate()
	{
		active = false;
		sessionToken = null;
		clientThread.invokeLater(() ->
		{
			botw.reset();
			botw.resetSoundObservation();
			sotw.reset();
			sotw.resetSoundObservation();
		});
	}

	void refreshState()
	{
		String token = sessionToken;
		if (!active || token == null || token.isBlank())
		{
			return;
		}
		refreshKind(botw, botwRefreshInFlight, token);
		refreshKind(sotw, sotwRefreshInFlight, token);
	}

	private void refreshKind(CompetitionContext context, AtomicBoolean inFlight, String token)
	{
		if (!inFlight.compareAndSet(false, true))
		{
			return;
		}
		apiClient.getCompetition(context.kind, token).whenComplete((response, error) ->
		{
			inFlight.set(false);
			clientThread.invokeLater(() -> applyState(context, token, response, error));
		});
	}

	private void applyState(
		CompetitionContext context,
		String requestedToken,
		SixthDegreeApiClient.CompetitionResponse response,
		Throwable error)
	{
		if (!active || !requestedToken.equals(sessionToken))
		{
			return;
		}
		if (error != null || response == null || !response.ok)
		{
			if (error != null)
			{
				log.debug("Sixth Degree {} state refresh failed", context.kind, error);
			}
			return;
		}
		SixthDegreeApiClient.Competition competition = response.active;
		boolean previouslyObserved = context.observedResponse;
		boolean previousEventHadWinner = context.eventId > 0 && context.hadQualifyingScore;
		if (competition == null || competition.event_id <= 0)
		{
			context.reset();
			context.observedResponse = true;
			if (previouslyObserved && previousEventHadWinner)
			{
				playWinnerSound();
			}
			return;
		}

		String newMetric = safe(competition.metric);
		boolean sameEvent = context.eventId == competition.event_id
			&& normalise(context.metric).equals(normalise(newMetric));
		boolean wasPaused = context.paused;
		if (!sameEvent)
		{
			context.reset();
			if (previouslyObserved && previousEventHadWinner)
			{
				playWinnerSound();
			}
		}

		context.eventId = competition.event_id;
		context.metric = newMetric;
		context.startTime = competition.start_time;
		context.endTime = competition.end_time;
		context.status = safe(competition.status).isBlank() ? "ACTIVE" : competition.status.toUpperCase(Locale.ROOT);
		context.paused = competition.paused;
		context.hadQualifyingScore = context.hadQualifyingScore || hasQualifyingScore(competition.standings);

		long now = nowSeconds();
		boolean nowLive = context.isScorable(now);
		if (nowLive)
		{
			if (previouslyObserved && context.soundedEventId != context.eventId
				&& config != null && config.notificationSound() && sounds != null)
			{
				sounds.play("BOTW".equals(context.kind)
					? SixthDegreeSoundService.Cue.BOTW
					: SixthDegreeSoundService.Cue.SOTW);
			}
			context.soundedEventId = context.eventId;
		}
		context.observedResponse = true;
		if ("SOTW".equals(context.kind))
		{
			context.skill = findSkill(context.metric);
			if (context.skill == null)
			{
				baselineTo(context, 0L);
				context.baselineObservationEstablished = false;
				return;
			}
			long currentXp = Math.max(0L, client.getSkillExperience(context.skill));
			if (!sameEvent)
			{
				// SOTW can read the player's absolute XP immediately. When Boss Lady says
				// the last accepted observation is safe to reconcile from, restore it and
				// submit any XP earned on mobile while the competition stayed live.
				if (context.isScorable(now) && competition.you != null && competition.reconcile_allowed)
				{
					long serverCurrent = Math.max(0L, competition.you.current_value);
					baselineTo(context, serverCurrent);
					context.baselineObservationEstablished = true;
					if (currentXp > serverCurrent)
					{
						context.latestValue = currentXp;
					}
				}
				else
				{
					// No trusted observation (or a pause occurred while RuneLite was away):
					// establish a fresh local baseline so lifetime/paused XP is never awarded.
					baselineTo(context, currentXp);
					context.baselineObservationEstablished = false;
				}
			}
			else if (!context.baselineSet || wasPaused != context.paused || !context.isScorable(now))
			{
				baselineTo(context, currentXp);
				if (wasPaused != context.paused || !context.isScorable(now))
				{
					context.baselineObservationEstablished = false;
				}
			}

			// A zero-score absolute observation makes the current desktop value safe to
			// reconcile from later. This is what lets mobile XP be recovered even when
			// the player switches away before earning any desktop XP in the competition.
			// It also establishes a new safe boundary immediately after a pause/resume.
			if (context.isScorable(now) && !context.baselineObservationEstablished)
			{
				submitBaselineObservation(context, currentXp);
			}
		}
		else
		{
			if (!sameEvent || wasPaused != context.paused || !context.isScorable(now))
			{
				context.needsFreshBossBaseline = true;
			}

			// On a fresh RuneLite session, restore the last absolute BOTW value only
			// when Boss Lady confirms no pause boundary occurred after that observation.
			// The next matching KC message can then backfill kills completed on mobile.
			if (!sameEvent && context.isScorable(now) && competition.you != null && competition.reconcile_allowed)
			{
				baselineTo(context, competition.you.current_value);
				context.needsFreshBossBaseline = false;
			}
		}

		if (context.isScorable(now))
		{
			flushProgress(context);
		}
	}

	private void submitBaselineObservation(CompetitionContext context, long currentValue)
	{
		if (!active || context.baselineObservationInFlight || !context.isScorable(nowSeconds()))
		{
			return;
		}
		String token = sessionToken;
		if (token == null || token.isBlank())
		{
			return;
		}

		final int eventId = context.eventId;
		final long observedAt = nowSeconds();
		final long safeValue = Math.max(0L, currentValue);
		final String telemetryId = baselineTelemetryId(context, safeValue, observedAt);
		context.baselineObservationInFlight = true;
		apiClient.postCompetitionProgress(
			context.kind,
			token,
			eventId,
			0L,
			safeValue,
			observedAt,
			telemetryId).whenComplete((response, error) ->
		{
			Runnable completion = () ->
			{
				if (context.eventId != eventId)
				{
					return;
				}
				context.baselineObservationInFlight = false;
				if (error == null && response != null && response.ok && !response.paused)
				{
					context.baselineObservationEstablished = true;
				}
			};
			if (clientThread != null)
			{
				clientThread.invokeLater(completion);
			}
			else
			{
				completion.run();
			}
		});
	}

	private void playWinnerSound()
	{
		if (config != null && config.notificationSound() && sounds != null)
		{
			sounds.play(SixthDegreeSoundService.Cue.WINNER);
		}
	}

	static boolean hasQualifyingScore(SixthDegreeApiClient.Standing[] standings)
	{
		if (standings == null)
		{
			return false;
		}
		for (SixthDegreeApiClient.Standing standing : standings)
		{
			if (standing != null && standing.score > 0L
				&& standing.rsn != null && !standing.rsn.isBlank())
			{
				return true;
			}
		}
		return false;
	}

	void onChatMessage(ChatMessage event)
	{
		if (!active || event == null || botw.eventId <= 0)
		{
			return;
		}
		BossCount count = parseBossCount(event.getMessage());
		if (count == null || !metricMatches(botw.metric, count.boss))
		{
			return;
		}

		long value = Math.max(0L, count.count);
		long now = nowSeconds();
		if (!botw.isScorable(now))
		{
			baselineTo(botw, value);
			botw.needsFreshBossBaseline = true;
			return;
		}

		if (!botw.baselineSet || botw.needsFreshBossBaseline)
		{
			botw.ackedValue = Math.max(0L, value - 1L);
			botw.latestValue = value;
			botw.baselineSet = true;
			botw.needsFreshBossBaseline = false;
		}
		else if (value > botw.latestValue)
		{
			botw.latestValue = value;
		}
		else
		{
			return;
		}
		flushProgress(botw);
	}

	void onStatChanged(StatChanged event)
	{
		if (!active || event == null || sotw.eventId <= 0 || sotw.skill == null || event.getSkill() != sotw.skill)
		{
			return;
		}
		long xp = Math.max(0L, event.getXp());
		long now = nowSeconds();
		if (!sotw.baselineSet || !sotw.isScorable(now))
		{
			baselineTo(sotw, xp);
			if (!sotw.isScorable(now))
			{
				sotw.baselineObservationEstablished = false;
			}
			return;
		}
		if (xp < sotw.latestValue)
		{
			// XP cannot legitimately decrease for the linked account. Ignore stale
			// login/stat events rather than lowering the trusted absolute baseline.
			return;
		}
		if (xp == sotw.latestValue)
		{
			return;
		}
		sotw.latestValue = xp;
		flushProgress(sotw);
	}

	private void flushProgress(CompetitionContext context)
	{
		if (!active || context.sending || !context.baselineSet || !context.isScorable(nowSeconds()))
		{
			return;
		}
		if (context.latestValue <= context.ackedValue)
		{
			return;
		}

		long maxDelta = "BOTW".equals(context.kind) ? MAX_BOTW_DELTA : MAX_SOTW_DELTA;
		if (context.pendingTarget <= context.ackedValue || context.pendingTarget > context.latestValue)
		{
			context.pendingTarget = Math.min(context.latestValue, context.ackedValue + maxDelta);
			context.pendingDelta = context.pendingTarget - context.ackedValue;
			context.pendingObservedAt = nowSeconds();
			context.pendingTelemetryId = telemetryId(context, context.pendingTarget);
		}
		if (context.pendingDelta <= 0L || context.pendingTelemetryId == null)
		{
			return;
		}

		String token = sessionToken;
		if (token == null || token.isBlank())
		{
			return;
		}
		final int eventId = context.eventId;
		final long target = context.pendingTarget;
		final long delta = context.pendingDelta;
		final long observedAt = context.pendingObservedAt;
		final String telemetryId = context.pendingTelemetryId;
		context.sending = true;

		apiClient.postCompetitionProgress(
			context.kind,
			token,
			eventId,
			delta,
			target,
			observedAt,
			telemetryId).whenComplete((response, error) ->
				clientThread.invokeLater(() -> handleProgressResult(
					context, eventId, target, response, error)));
	}

	private void handleProgressResult(
		CompetitionContext context,
		int eventId,
		long target,
		SixthDegreeApiClient.CompetitionProgressResponse response,
		Throwable error)
	{
		context.sending = false;
		if (context.eventId != eventId)
		{
			return;
		}
		if (error != null)
		{
			Throwable cause = unwrap(error);
			if (cause instanceof SixthDegreeApiClient.ApiException)
			{
				int code = ((SixthDegreeApiClient.ApiException) cause).getStatusCode();
				if (code == 400 || code == 401 || code == 403 || code == 404 || code == 409)
				{
					clearPending(context);
					refreshState();
				}
			}
			return;
		}
		if (response == null || !response.ok)
		{
			return;
		}

		if (response.paused)
		{
			baselineTo(context, Math.max(context.latestValue, target));
			if ("BOTW".equals(context.kind))
			{
				context.needsFreshBossBaseline = true;
			}
			else
			{
				context.baselineObservationEstablished = false;
			}
			refreshState();
			return;
		}

		// accepted=false without paused means Boss Lady already saw this deterministic
		// telemetry ID. Treat it as acknowledged so a lost HTTP response cannot double-count.
		context.ackedValue = Math.max(context.ackedValue, target);
		context.latestValue = Math.max(context.latestValue, context.ackedValue);
		context.baselineSet = true;
		clearPending(context);
		flushProgress(context);
	}

	private static void baselineTo(CompetitionContext context, long value)
	{
		long safeValue = Math.max(0L, value);
		context.ackedValue = safeValue;
		context.latestValue = safeValue;
		context.baselineSet = true;
		clearPending(context);
	}

	private static void clearPending(CompetitionContext context)
	{
		context.pendingTarget = -1L;
		context.pendingDelta = 0L;
		context.pendingObservedAt = 0L;
		context.pendingTelemetryId = null;
	}

	private String telemetryId(CompetitionContext context, long target)
	{
		return context.kind.toLowerCase(Locale.ROOT)
			+ ":" + context.eventId
			+ ":" + accountDiscriminator()
			+ ":" + target;
	}

	private String baselineTelemetryId(CompetitionContext context, long value, long observedAt)
	{
		return context.kind.toLowerCase(Locale.ROOT)
			+ ":" + context.eventId
			+ ":" + accountDiscriminator()
			+ ":baseline:" + value
			+ ":" + observedAt;
	}

	private String accountDiscriminator()
	{
		Player player = client.getLocalPlayer();
		String name = player == null ? "unknown" : safe(player.getName());
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(normalise(name).getBytes(StandardCharsets.UTF_8));
			StringBuilder out = new StringBuilder();
			for (int i = 0; i < 6; i++)
			{
				out.append(String.format(Locale.ROOT, "%02x", digest[i]));
			}
			return out.toString();
		}
		catch (Exception ignored)
		{
			return "unknown000000";
		}
	}

	private static Skill findSkill(String metric)
	{
		String wanted = normalise(metric);
		if (wanted.isBlank())
		{
			return null;
		}
		for (Skill skill : Skill.values())
		{
			if (normalise(skill.getName()).equals(wanted))
			{
				return skill;
			}
		}
		return null;
	}

	static boolean metricMatches(String configured, String observed)
	{
		String a = normaliseBoss(configured);
		String b = normaliseBoss(observed);
		if (a.isBlank() || b.isBlank())
		{
			return false;
		}
		if (isGotr(configured) || isGotr(observed))
		{
			return isGotr(configured) && isGotr(observed);
		}
		return a.equals(b) || (a.length() >= 5 && b.length() >= 5 && (a.contains(b) || b.contains(a)));
	}

	static BossCount parseBossCount(String rawMessage)
	{
		if (rawMessage == null || rawMessage.isBlank())
		{
			return null;
		}
		String message = Text.removeTags(rawMessage).trim();
		Matcher rifts = RIFTS_CLOSED.matcher(message);
		if (rifts.matches())
		{
			try
			{
				return new BossCount("GOTR", Long.parseLong(rifts.group(1).replace(",", "")));
			}
			catch (NumberFormatException ignored)
			{
				return null;
			}
		}
		Matcher matcher = BOSS_COUNT.matcher(message);
		if (!matcher.find())
		{
			matcher = BOSS_COUNT_SECONDARY.matcher(message);
			if (!matcher.find())
			{
				return null;
			}
		}
		try
		{
			String boss = matcher.group(1).trim();
			long count = Long.parseLong(matcher.group(2).replace(",", ""));
			return boss.isBlank() ? null : new BossCount(boss, count);
		}
		catch (Exception ignored)
		{
			return null;
		}
	}

	static boolean isGotr(String metric)
	{
		String value = normalise(metric);
		return value.equals("gotr") || value.equals("guardians of the rift") || value.equals("rifts closed");
	}

	private static String normaliseBoss(String value)
	{
		String normalised = normalise(value);
		return normalised.startsWith("the ") ? normalised.substring(4) : normalised;
	}

	private static String normalise(String value)
	{
		String clean = Text.removeTags(safe(value)).toLowerCase(Locale.ROOT)
			.replace('&', ' ')
			.replaceAll("[^a-z0-9]+", " ")
			.trim();
		return clean.replaceAll("\\s+", " ");
	}

	private static String safe(String value)
	{
		return value == null ? "" : value.trim();
	}

	private static long nowSeconds()
	{
		return System.currentTimeMillis() / 1000L;
	}

	private static Throwable unwrap(Throwable throwable)
	{
		Throwable current = throwable;
		while (current != null && current.getCause() != null
			&& current.getClass().getName().contains("Completion"))
		{
			current = current.getCause();
		}
		return current == null ? throwable : current;
	}

	private static final class CompetitionContext
	{
		final String kind;
		int eventId;
		String metric = "";
		long startTime;
		long endTime;
		String status = "";
		boolean paused;
		Skill skill;
		long ackedValue;
		long latestValue;
		boolean baselineSet;
		boolean baselineObservationEstablished;
		boolean baselineObservationInFlight;
		boolean needsFreshBossBaseline = true;
		boolean sending;
		long pendingTarget = -1L;
		long pendingDelta;
		long pendingObservedAt;
		String pendingTelemetryId;
		boolean observedResponse;
		int soundedEventId;
		boolean hadQualifyingScore;

		CompetitionContext(String kind)
		{
			this.kind = kind;
		}

		boolean isScorable(long now)
		{
			return "ACTIVE".equals(status)
				&& !paused
				&& eventId > 0
				&& now >= startTime
				&& now <= endTime;
		}

		void reset()
		{
			eventId = 0;
			metric = "";
			startTime = 0L;
			endTime = 0L;
			status = "";
			paused = false;
			skill = null;
			ackedValue = 0L;
			latestValue = 0L;
			baselineSet = false;
			baselineObservationEstablished = false;
			baselineObservationInFlight = false;
			needsFreshBossBaseline = true;
			sending = false;
			hadQualifyingScore = false;
			clearPending(this);
		}

		void resetSoundObservation()
		{
			observedResponse = false;
			soundedEventId = 0;
		}
	}

	static final class BossCount
	{
		final String boss;
		final long count;

		BossCount(String boss, long count)
		{
			this.boss = boss;
			this.count = count;
		}
	}
}

