package com.sixthdegree;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

@Singleton
final class SixthDegreeLootService
{
	private final Client client;
	private final ItemManager itemManager;
	private final Deque<Batch> pending = new ArrayDeque<>();
	private final List<String> signaturesThisTick = new ArrayList<>();

	private int signatureTick = -1;
	private long bucketValueGp;
	private int bucketDropCount;

	@Inject
	SixthDegreeLootService(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/**
	 * Value one RuneLite loot event. This intentionally happens before any
	 * notification/screenshot filtering: every unique drop contributes to the fun
	 * clan GP leaderboard.
	 */
	void record(Collection<ItemStack> items)
	{
		if (items == null || items.isEmpty())
		{
			return;
		}

		int tick = client.getTickCount();
		String signature = signature(items);
		synchronized (this)
		{
			if (tick != signatureTick)
			{
				signatureTick = tick;
				signaturesThisTick.clear();
			}
			// RuneLite exposes some rewards through more than one loot event. Treat the
			// same item payload in the same game tick as one drop to avoid double-counting.
			if (signaturesThisTick.contains(signature))
			{
				return;
			}
			signaturesThisTick.add(signature);
		}

		long total = 0L;
		for (ItemStack item : items)
		{
			if (item == null || item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			long unitPrice = price(item.getId());
			if (unitPrice > 0)
			{
				total += unitPrice * (long) item.getQuantity();
			}
		}

		synchronized (this)
		{
			bucketValueGp += Math.max(0L, total);
			bucketDropCount++;
		}
	}

	private long price(int itemId)
	{
		try
		{
			long price = itemManager.getItemPrice(itemId);
			if (price > 0)
			{
				return price;
			}
			ItemComposition composition = itemManager.getItemComposition(itemId);
			return composition == null ? 0L : Math.max(0, composition.getPrice());
		}
		catch (Exception ignored)
		{
			return 0L;
		}
	}

	synchronized void sealBatch()
	{
		if (bucketDropCount <= 0)
		{
			return;
		}
		pending.addLast(new Batch(
			UUID.randomUUID().toString(),
			bucketValueGp,
			bucketDropCount,
			System.currentTimeMillis() / 1000L));
		bucketValueGp = 0L;
		bucketDropCount = 0;

		// If Boss Lady is unreachable for a very long time, keep memory bounded while
		// still retaining a generous amount of unsent gameplay.
		while (pending.size() > 120)
		{
			Batch first = pending.removeFirst();
			Batch second = pending.pollFirst();
			if (second == null)
			{
				pending.addFirst(first);
				break;
			}
			pending.addFirst(new Batch(
				second.id,
				first.valueGp + second.valueGp,
				first.dropCount + second.dropCount,
				second.recordedAt));
		}
	}

	synchronized Batch peekBatch()
	{
		return pending.peekFirst();
	}

	synchronized void acknowledge(String batchId)
	{
		Batch current = pending.peekFirst();
		if (current != null && current.id.equals(batchId))
		{
			pending.removeFirst();
		}
	}

	synchronized boolean hasPending()
	{
		return !pending.isEmpty() || bucketDropCount > 0;
	}

	private static String signature(Collection<ItemStack> items)
	{
		List<String> values = new ArrayList<>(items.size());
		for (ItemStack item : items)
		{
			if (item != null)
			{
				values.add(item.getId() + "x" + item.getQuantity());
			}
		}
		Collections.sort(values);
		return String.join(",", values);
	}

	static final class Batch
	{
		final String id;
		final long valueGp;
		final int dropCount;
		final long recordedAt;

		Batch(String id, long valueGp, int dropCount, long recordedAt)
		{
			this.id = id;
			this.valueGp = valueGp;
			this.dropCount = dropCount;
			this.recordedAt = recordedAt;
		}
	}
}

package com.sixthdegree;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.CompletionException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
@Singleton
final class SixthDegreeNotificationCoordinator
{
	private static final int MAX_PENDING = 30;
	private static final long RULE_REFRESH_MINUTES = 5L;

	private final SixthDegreeNotificationEngine engine;
	private final SixthDegreeScreenshotService screenshots;
	private final SixthDegreeRarityService rarityService;
	private final SixthDegreeCompetitionTracker competitionTracker;
	private final SixthDegreeSoundService sounds;
	private final SixthDegreeConfig config;
	private final Deque<PendingNotification> pending = new ArrayDeque<>();
	private final AtomicBoolean sending = new AtomicBoolean(false);
	private final AtomicBoolean rulesRefreshing = new AtomicBoolean(false);
	private final AtomicBoolean rarityRefreshing = new AtomicBoolean(false);

	private SixthDegreeApiClient apiClient;
	private ScheduledExecutorService scheduler;
	private volatile String sessionToken;
	private volatile boolean active;
	private long lastQuestSoundAt;

	@Inject
	SixthDegreeNotificationCoordinator(
		SixthDegreeNotificationEngine engine,
		SixthDegreeScreenshotService screenshots,
		SixthDegreeRarityService rarityService,
		SixthDegreeCompetitionTracker competitionTracker,
		SixthDegreeSoundService sounds,
		SixthDegreeConfig config)
	{
		this.engine = engine;
		this.screenshots = screenshots;
		this.rarityService = rarityService;
		this.competitionTracker = competitionTracker;
		this.sounds = sounds;
		this.config = config;
	}

	void start(SixthDegreeApiClient apiClient)
	{
		this.apiClient = apiClient;
		competitionTracker.start();
		if (scheduler == null || scheduler.isShutdown())
		{
			scheduler = Executors.newSingleThreadScheduledExecutor(r ->
			{
				Thread thread = new Thread(r, "sixth-degree-notifications");
				thread.setDaemon(true);
				return thread;
			});
			scheduler.scheduleAtFixedRate(
				this::refreshRules,
				RULE_REFRESH_MINUTES,
				RULE_REFRESH_MINUTES,
				TimeUnit.MINUTES);
			scheduler.scheduleAtFixedRate(this::flush, 10, 10, TimeUnit.SECONDS);
		}
	}

	void stop()
	{
		deactivate();
		competitionTracker.stop();
		if (scheduler != null)
		{
			scheduler.shutdownNow();
			scheduler = null;
		}
		synchronized (pending)
		{
			pending.clear();
		}
		sending.set(false);
	}

	void activate(String token)
	{
		if (token == null || token.isBlank())
		{
			return;
		}
		boolean changed = !active || !token.equals(sessionToken);
		sessionToken = token;
		active = true;
		competitionTracker.activate(token);
		if (changed)
		{
			engine.reset();
			engine.initializeStats();
			refreshRules();
			flush();
		}
	}

	void deactivate()
	{
		active = false;
		sessionToken = null;
		competitionTracker.deactivate();
		engine.setRules(SixthDegreeNotificationRules.DISABLED);
		engine.reset();
	}

	void refreshCompetitionState()
	{
		competitionTracker.refreshState();
	}

	void refreshRules()
	{
		String token = sessionToken;
		if (!active || token == null || token.isBlank() || apiClient == null
			|| !rulesRefreshing.compareAndSet(false, true))
		{
			return;
		}
		apiClient.getNotificationRules(token).whenComplete((response, error) ->
		{
			rulesRefreshing.set(false);
			if (error != null || response == null || !response.ok)
			{
				return;
			}

			SixthDegreeNotificationRules parsed = SixthDegreeNotificationRules.from(response.rules);
			if (parsed.loot.rarityOverride > 0 && !rarityService.isLoaded())
			{
				// Avoid a small startup window where value notifications work but a rare,
				// low-value drop could be missed before its rarity table is ready.
				engine.setRules(SixthDegreeNotificationRules.DISABLED);
				loadRarityData(token, parsed);
				return;
			}
			engine.setRules(parsed);
		});
	}

	private void loadRarityData(String token, SixthDegreeNotificationRules parsed)
	{
		if (!rarityRefreshing.compareAndSet(false, true))
		{
			return;
		}
		apiClient.getNpcDropRarityData(token).whenComplete((json, error) ->
		{
			rarityRefreshing.set(false);
			if (!active || !token.equals(sessionToken))
			{
				return;
			}
			if (error == null && rarityService.load(json))
			{
				log.debug("Sixth Degree NPC rarity data loaded");
			}
			else if (error != null)
			{
				log.warn("Sixth Degree rarity data unavailable; value-based loot notifications remain active", error);
			}
			engine.setRules(parsed);
		});
	}

	@Subscribe(priority = 0)
	public void onNpcLootReceived(NpcLootReceived event)
	{
		if (!active)
		{
			return;
		}
		String source = event.getNpc() == null ? "NPC" : event.getNpc().getName();
		dispatch(engine.onLoot(event.getItems(), source));
	}

	@Subscribe(priority = 0)
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (!active)
		{
			return;
		}
		String source = event.getComposition() == null ? "NPC" : event.getComposition().getName();
		dispatch(engine.onLoot(event.getItems(), source));
	}

	@Subscribe(priority = 0)
	public void onLootReceived(LootReceived event)
	{
		if (!active)
		{
			return;
		}
		LootRecordType type = event.getType();
		// Normal NPC loot already arrives through NpcLootReceived/ServerNpcLoot.
		// Processing LootReceived(NPC) as well can represent the same kill twice.
		if (type != LootRecordType.EVENT && type != LootRecordType.PICKPOCKET)
		{
			return;
		}
		dispatch(engine.onLoot(event.getItems(), event.getName()));
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!active || event == null)
		{
			return;
		}
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE
			&& type != ChatMessageType.SPAM
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}
		competitionTracker.onChatMessage(event);
		List<SixthDegreeNotificationEvent> events = engine.onGameMessage(event.getMessage());
		for (SixthDegreeNotificationEvent notification : events)
		{
			dispatch(notification);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!active)
		{
			return;
		}
		competitionTracker.onStatChanged(event);
		for (SixthDegreeNotificationEvent notification : engine.onStatChanged(event))
		{
			dispatch(notification);
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!active)
		{
			return;
		}
		SixthDegreeNotificationEvent notification = engine.onActorDeath(event);
		if (notification != null && !config.deathScreenshots())
		{
			notification = notification.withScreenshot(false);
		}
		dispatch(notification);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!active || event == null || event.getGroupId() != InterfaceID.QUESTSCROLL)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now - lastQuestSoundAt < 3_000L)
		{
			return;
		}
		lastQuestSoundAt = now;
		if (config.notificationSound())
		{
			sounds.play(SixthDegreeSoundService.Cue.QUEST);
		}
		dispatch(engine.onQuestCompleted());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			engine.reset();
		}
	}

	private void dispatch(SixthDegreeNotificationEvent event)
	{
		if (event == null || !active)
		{
			return;
		}
		playEventSound(event);
		log.info(
			"Sixth Degree notification detected: {} (screenshot: {})",
			event.type,
			event.screenshot ? "requested" : "off");

		if (!event.screenshot)
		{
			enqueue(new PendingNotification(event, null));
			return;
		}

		screenshots.capturePng().whenComplete((png, error) ->
		{
			if (error != null)
			{
				log.warn(
					"Sixth Degree screenshot capture failed for {} - posting without image: {}",
					event.type,
					errorMessage(error));
				enqueue(new PendingNotification(event, null));
			}
			else
			{
				enqueue(new PendingNotification(event, png));
			}
		});
	}

	private void playEventSound(SixthDegreeNotificationEvent event)
	{
		if (!config.notificationSound())
		{
			return;
		}
		if ("death".equals(event.type))
		{
			sounds.play(SixthDegreeSoundService.Cue.DEATH);
		}
		else if ("collection_log".equals(event.type))
		{
			sounds.play(SixthDegreeSoundService.Cue.COLLECTION_LOG);
		}
		else if ("boss_pb".equals(event.type)
			&& event.title != null
			&& event.title.toLowerCase(java.util.Locale.ROOT).contains("personal best"))
		{
			sounds.play(SixthDegreeSoundService.Cue.PERSONAL_BEST);
		}
	}

	private void enqueue(PendingNotification notification)
	{
		if (!active)
		{
			return;
		}
		synchronized (pending)
		{
			while (pending.size() >= MAX_PENDING)
			{
				pending.removeFirst();
			}
			pending.addLast(notification);
		}
		flush();
	}

	private void flush()
	{
		String token = sessionToken;
		if (!active || token == null || token.isBlank() || apiClient == null
			|| !sending.compareAndSet(false, true))
		{
			return;
		}

		PendingNotification next;
		synchronized (pending)
		{
			next = pending.peekFirst();
		}
		if (next == null)
		{
			sending.set(false);
			return;
		}

		apiClient.postNotification(token, next.event, next.png).whenComplete((response, error) ->
		{
			boolean remove = error == null && response != null && response.ok;
			boolean retry = false;
			if (error == null && response != null && response.ok)
			{
				if (response.duplicate)
				{
					log.info("Sixth Degree notification duplicate ignored: {}", next.event.type);
				}
				else
				{
					log.info(
						"Sixth Degree notification sent: {} (screenshot: {})",
						next.event.type,
						next.png == null ? "no" : "yes");
				}
			}
			if (error != null)
			{
				Throwable cause = unwrap(error);
				if (cause instanceof SixthDegreeApiClient.ApiException)
				{
					int code = ((SixthDegreeApiClient.ApiException) cause).getStatusCode();
					remove = isPermanentNotificationFailure(code);
					if (code == 409)
					{
						refreshRules();
					}
					if (code == 413 && next.png != null)
					{
						log.warn(
							"Sixth Degree screenshot upload rejected for {}: HTTP 413 {} (image {})",
							next.event.type,
							errorMessage(cause),
							formatBytes(next.png.length));
					}
					else
					{
						log.warn(
							"Sixth Degree notification upload failed for {}: HTTP {} {}",
							next.event.type,
							code,
							errorMessage(cause));
					}
				}
				else
				{
					log.warn(
						"Sixth Degree notification transport failed for {}: {}",
						next.event.type,
						errorMessage(cause));
					retry = true;
				}
				if (!remove)
				{
					next.attempts++;
					retry = next.attempts < 5;
					remove = !retry;
					if (remove)
					{
						log.warn(
							"Sixth Degree notification abandoned after {} attempts: {}",
							next.attempts,
							next.event.type);
					}
				}
			}

			if (remove)
			{
				synchronized (pending)
				{
					if (pending.peekFirst() == next)
					{
						pending.removeFirst();
					}
				}
			}
			sending.set(false);

			if (!retry && active && scheduler != null && !scheduler.isShutdown())
			{
				scheduler.schedule(this::flush, 250, TimeUnit.MILLISECONDS);
			}
		});
	}

	static boolean isPermanentNotificationFailure(int code)
	{
		return code == 400 || code == 401 || code == 403 || code == 409 || code == 413;
	}

	private static String formatBytes(int bytes)
	{
		if (bytes >= 1024 * 1024)
		{
			return String.format(java.util.Locale.UK, "%.2f MiB", bytes / (1024.0 * 1024.0));
		}
		return Math.max(0, bytes / 1024) + " KiB";
	}

	private static String errorMessage(Throwable throwable)
	{
		Throwable cause = unwrap(throwable);
		if (cause == null)
		{
			return "unknown error";
		}
		String message = cause.getMessage();
		return message == null || message.isBlank() ? cause.getClass().getSimpleName() : message;
	}

	private static Throwable unwrap(Throwable throwable)
	{
		Throwable current = throwable;
		while (current instanceof CompletionException && current.getCause() != null)
		{
			current = current.getCause();
		}
		return current;
	}

	private static final class PendingNotification
	{
		final SixthDegreeNotificationEvent event;
		final byte[] png;
		int attempts;

		PendingNotification(SixthDegreeNotificationEvent event, byte[] png)
		{
			this.event = event;
			this.png = png;
		}
	}
}

package com.sixthdegree;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.util.Text;

@Singleton
final class SixthDegreeNotificationEngine
{
	private static final String COLLECTION_LOG_PREFIX = "New item added to your collection log:";
	private static final Pattern QUEST_PATTERN_1 = Pattern.compile(".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: [Qq]uest)?[!.]?$");
	private static final Pattern QUEST_PATTERN_2 = Pattern.compile("'?(?<quest>.+?)'?(?: [Qq]uest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$");
	private static final Set<String> RFD_TAGS = Set.of("Another Cook", "freed", "defeated", "saved");
	private static final Set<String> WORD_QUEST_IN_NAME_TAGS = Set.of("Another Cook", "Doric", "Heroes", "Legends", "Observatory", "Olaf", "Waterfall");
	private static final Map<String, String> QUEST_REPLACEMENTS = Map.of(
		"Lumbridge Cook... again", "Another Cook's",
		"Skrach 'Bone Crusher' Uglogwee", "Skrach Uglogwee");
	private static final Pattern BOSS_COUNT = Pattern.compile(
		"Your (.+?)\\s(?:kill|chest|completion|harvest|success|opened)\\s?count is: ?([\\d,]+)\\b",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern BOSS_COUNT_SECONDARY = Pattern.compile(
		"Your (?:completed|subdued) (.+?) count is: ([\\d,]+)\\b",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern COMBAT_TASK = Pattern.compile(
		"congratulations, you(?:'ve| have) completed an? (easy|medium|hard|elite|master|grandmaster) combat task: (.+?)[.!]?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern BOSS_TIME = Pattern.compile(
		"(?:Duration|time|Subdued in):? ([\\d:]+(?:\\.\\d+)?)",
		Pattern.CASE_INSENSITIVE);
	private static final int BOSS_CONTEXT_TICKS = 10;

	private final Client client;
	private final ItemManager itemManager;
	private final SixthDegreeRarityService rarityService;
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
	private final List<String> lootSignaturesThisTick = new ArrayList<>();

	private volatile SixthDegreeNotificationRules rules = SixthDegreeNotificationRules.DISABLED;
	private int lootSignatureTick = -1;
	private String lastBoss;
	private int lastBossCount;
	private int lastBossTick = -1000;
	private int lastTotalLevel;

	@Inject
	SixthDegreeNotificationEngine(
		Client client,
		ItemManager itemManager,
		SixthDegreeRarityService rarityService)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.rarityService = rarityService;
	}

	void setRules(SixthDegreeNotificationRules rules)
	{
		this.rules = rules == null ? SixthDegreeNotificationRules.DISABLED : rules;
	}

	SixthDegreeNotificationRules getRules()
	{
		return rules;
	}

	void initializeStats()
	{
		levels.clear();
		experience.clear();
		for (Skill skill : Skill.values())
		{
			levels.put(skill, Math.max(1, client.getRealSkillLevel(skill)));
			experience.put(skill, Math.max(0, client.getSkillExperience(skill)));
		}
		lastTotalLevel = Math.max(0, client.getTotalLevel());
	}

	SixthDegreeNotificationEvent onQuestCompleted()
	{
		SixthDegreeNotificationRules current = rules;
		if (!current.engineLive || !current.quests.enabled)
		{
			return null;
		}
		Widget questWidget = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
		if (questWidget == null)
		{
			return null;
		}
		String quest = parseQuestWidget(Text.removeTags(questWidget.getText()).trim());
		if (quest == null || quest.isBlank())
		{
			return null;
		}
		return SixthDegreeNotificationEvent.of(
			"quest",
			quest,
			"Quest completed.",
			"Quest",
			0L,
			current.quests.screenshots);
	}

	SixthDegreeNotificationEvent onActorDeath(ActorDeath event)
	{
		SixthDegreeNotificationRules current = rules;
		if (!current.engineLive || !current.deaths.enabled || event == null
			|| event.getActor() != client.getLocalPlayer())
		{
			return null;
		}
		return SixthDegreeNotificationEvent.of(
			"death",
			"Oh dear, you are dead!",
			"A clan member has died.",
			"",
			0L,
			current.deaths.screenshots);
	}

	void reset()
	{
		levels.clear();
		experience.clear();
		lootSignaturesThisTick.clear();
		lootSignatureTick = -1;
		lastBoss = null;
		lastBossCount = 0;
		lastBossTick = -1000;
		lastTotalLevel = 0;
	}

	SixthDegreeNotificationEvent onLoot(Collection<ItemStack> items, String source)
	{
		SixthDegreeNotificationRules current = rules;
		if (!current.engineLive || !current.loot.enabled || items == null || items.isEmpty())
		{
			return null;
		}

		List<ItemStack> reduced = reduceItems(items);
		if (reduced.isEmpty() || duplicateLootThisTick(reduced, source))
		{
			return null;
		}

		List<DropPart> parts = new ArrayList<>();
		long total = 0L;
		for (ItemStack stack : reduced)
		{
			long unit = price(stack.getId());
			long value = Math.max(0L, unit * (long) stack.getQuantity());
			total += value;
			parts.add(new DropPart(
				stack.getId(), itemName(stack.getId()), stack.getQuantity(), value));
		}

		String cleanSource = safeSource(source, "Loot");
		boolean valueTriggered = parts.stream()
			.anyMatch(part -> part.value >= current.loot.minimumValue);
		boolean rarityTriggered = !valueTriggered
			&& current.loot.rarityOverride > 0
			&& rarityService.qualifies(cleanSource, reduced, current.loot.rarityOverride);
		if (!valueTriggered && !rarityTriggered)
		{
			return null;
		}

		parts.sort(Comparator.comparingLong((DropPart part) -> part.value).reversed());
		String title;
		if (parts.size() == 1)
		{
			title = parts.get(0).name;
		}
		else
		{
			title = rarityTriggered ? "Rare loot" : "Valuable loot";
		}

		String detail = parts.stream()
			.limit(8)
			.map(part -> part.quantity + " x " + part.name + " — " + formatGp(part.value))
			.collect(Collectors.joining("\n"));

		int thumbnailItemId = parts.isEmpty() ? 0 : parts.get(0).itemId;
		return SixthDegreeNotificationEvent.loot(
			title,
			detail,
			cleanSource,
			total,
			current.loot.screenshots && total >= current.loot.screenshotMinimumValue,
			thumbnailItemId,
			rarityTriggered);
	}

	List<SixthDegreeNotificationEvent> onGameMessage(String rawMessage)
	{
		List<SixthDegreeNotificationEvent> events = new ArrayList<>(2);
		SixthDegreeNotificationRules current = rules;
		if (!current.engineLive || rawMessage == null || rawMessage.isBlank())
		{
			return events;
		}

		String message = Text.removeTags(rawMessage).trim();
		String lower = message.toLowerCase(Locale.ROOT);

		if (current.pets.enabled && isPetMessage(lower))
		{
			events.add(SixthDegreeNotificationEvent.of(
				"pet",
				"New pet!",
				message,
				"Pet drop",
				0L,
				current.pets.screenshots));
		}

		if (current.combatAchievements.enabled)
		{
			Matcher combatTask = COMBAT_TASK.matcher(message);
			if (combatTask.matches())
			{
				String tier = combatTask.group(1);
				String task = combatTask.group(2).trim();
				if (!task.isBlank())
				{
					events.add(SixthDegreeNotificationEvent.of(
						"combat_achievement",
						task,
						"Completed a " + tier.toLowerCase(Locale.ROOT) + " combat task.",
						tier,
						0L,
						current.combatAchievements.screenshots));
				}
			}
		}

		if (current.collectionLogs.enabled && message.startsWith(COLLECTION_LOG_PREFIX))
		{
			String item = message.substring(COLLECTION_LOG_PREFIX.length()).trim();
			events.add(SixthDegreeNotificationEvent.of(
				"collection_log",
				item.isBlank() ? "New collection log item" : item,
				"New item added to the collection log.",
				"Collection Log",
				0L,
				current.collectionLogs.screenshots));
		}

		if (current.bossPbs.enabled)
		{
			BossCount count = parseBossCount(message);
			if (count != null)
			{
				lastBoss = count.boss;
				lastBossCount = count.count;
				lastBossTick = client.getTickCount();
				if ((count.count == 1 && current.bossPbs.notifyInitial)
					|| (current.bossPbs.killCountInterval > 0
						&& count.count % current.bossPbs.killCountInterval == 0))
				{
					events.add(SixthDegreeNotificationEvent.of(
						"boss_pb",
						count.boss + " milestone",
						"Kill count: " + count.count,
						count.boss,
						0L,
						current.bossPbs.screenshots));
				}
			}

			if (current.bossPbs.notifyPersonalBests
				&& lower.contains("new personal best")
				&& BOSS_TIME.matcher(message).find())
			{
				String boss = bossContext();
				events.add(SixthDegreeNotificationEvent.of(
					"boss_pb",
					boss + " — new personal best",
					message,
					boss,
					0L,
					current.bossPbs.screenshots));
			}
		}

		return events;
	}

	List<SixthDegreeNotificationEvent> onStatChanged(StatChanged event)
	{
		List<SixthDegreeNotificationEvent> events = new ArrayList<>(1);
		if (event == null)
		{
			return events;
		}

		Skill skill = event.getSkill();
		int level = event.getLevel();
		int xp = event.getXp();
		Integer previousLevel = levels.put(skill, level);
		Integer previousXp = experience.put(skill, xp);
		int previousTotalLevel = lastTotalLevel;
		int totalLevel = Math.max(0, client.getTotalLevel());
		if (totalLevel > 0)
		{
			lastTotalLevel = totalLevel;
		}

		SixthDegreeNotificationRules current = rules;
		if (!current.engineLive || !current.milestones.enabled || previousLevel == null || previousXp == null)
		{
			return events;
		}
		if (level < previousLevel || xp < previousXp)
		{
			reset();
			return events;
		}

		if (level > previousLevel && shouldNotifyLevel(previousLevel, level, current.milestones))
		{
			boolean totalMilestone = totalLevel > previousTotalLevel && totalLevel > 0 && totalLevel % 100 == 0;
			String title = skill.getName() + " level " + level;
			if (totalMilestone)
			{
				title += " • " + formatNumber(totalLevel) + " total";
			}
			String detail = "Reached level " + level + " " + skill.getName() + ".";
			if (totalLevel > 0)
			{
				detail += " Total level: " + formatNumber(totalLevel) + ".";
			}
			events.add(SixthDegreeNotificationEvent.of(
				"milestone",
				title,
				detail,
				skill.getName(),
				0L,
				current.milestones.screenshots && level >= current.milestones.screenshotMinimumLevel));
			return events;
		}

		int millions = current.milestones.xpIntervalMillions;
		if (millions > 0 && level >= 99 && xp > previousXp)
		{
			long interval = millions * 1_000_000L;
			long oldBucket = previousXp / interval;
			long newBucket = xp / interval;
			if (newBucket > oldBucket)
			{
				long milestone = newBucket * interval;
				events.add(SixthDegreeNotificationEvent.of(
					"milestone",
					skill.getName() + " XP milestone",
					"Reached " + formatNumber(milestone) + " " + skill.getName() + " XP.",
					skill.getName(),
					0L,
					current.milestones.screenshots));
			}
		}
		return events;
	}

	private static List<ItemStack> reduceItems(Collection<ItemStack> items)
	{
		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (ItemStack item : items)
		{
			if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
			{
				quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		List<ItemStack> reduced = new ArrayList<>(quantities.size());
		for (Map.Entry<Integer, Integer> entry : quantities.entrySet())
		{
			reduced.add(new ItemStack(entry.getKey(), entry.getValue()));
		}
		return reduced;
	}

	private boolean duplicateLootThisTick(Collection<ItemStack> items, String source)
	{
		int tick = client.getTickCount();
		if (tick != lootSignatureTick)
		{
			lootSignatureTick = tick;
			lootSignaturesThisTick.clear();
		}
		String signature = safeSource(source, "Loot") + "|" + items.stream()
			.filter(item -> item != null)
			.map(item -> item.getId() + "x" + item.getQuantity())
			.sorted()
			.collect(Collectors.joining(","));
		if (lootSignaturesThisTick.contains(signature))
		{
			return true;
		}
		lootSignaturesThisTick.add(signature);
		return false;
	}

	private long price(int itemId)
	{
		try
		{
			long ge = itemManager.getItemPrice(itemId);
			if (ge > 0)
			{
				return ge;
			}
			ItemComposition composition = itemManager.getItemComposition(itemId);
			return composition == null ? 0L : Math.max(0, composition.getPrice());
		}
		catch (Exception ignored)
		{
			return 0L;
		}
	}

	private String itemName(int itemId)
	{
		try
		{
			ItemComposition composition = itemManager.getItemComposition(itemId);
			String name = composition == null ? null : composition.getName();
			return name == null || name.isBlank() ? "Item " + itemId : name;
		}
		catch (Exception ignored)
		{
			return "Item " + itemId;
		}
	}

	private static boolean isPetMessage(String lower)
	{
		return (lower.contains("funny feeling") && lower.contains("followed"))
			|| lower.contains("weird sneaking into your backpack");
	}

	private static String parseQuestWidget(String text)
	{
		if (text == null || text.isBlank())
		{
			return null;
		}
		Matcher matcher = QUEST_PATTERN_1.matcher(text);
		if (!matcher.matches())
		{
			matcher = QUEST_PATTERN_2.matcher(text);
			if (!matcher.matches())
			{
				return null;
			}
		}
		String quest = matcher.group("quest");
		quest = QUEST_REPLACEMENTS.getOrDefault(quest, quest);
		String verb = matcher.group("verb");
		verb = verb == null ? "" : verb;
		if (verb.contains("kind of"))
		{
			return null;
		}
		if (verb.contains("completely"))
		{
			quest += " II";
		}
		String combined = quest + verb;
		for (String tag : RFD_TAGS)
		{
			if (combined.contains(tag))
			{
				quest = "Recipe for Disaster - " + quest;
				break;
			}
		}
		for (String tag : WORD_QUEST_IN_NAME_TAGS)
		{
			if (quest.contains(tag))
			{
				quest += " Quest";
				break;
			}
		}
		return quest.trim();
	}

	private BossCount parseBossCount(String message)
	{
		Matcher matcher = BOSS_COUNT.matcher(message);
		if (!matcher.find())
		{
			matcher = BOSS_COUNT_SECONDARY.matcher(message);
			if (!matcher.find())
			{
				return null;
			}
		}
		try
		{
			String boss = matcher.group(1).trim();
			int count = Integer.parseInt(matcher.group(2).replace(",", ""));
			return boss.isBlank() ? null : new BossCount(boss, count);
		}
		catch (Exception ignored)
		{
			return null;
		}
	}

	private String bossContext()
	{
		if (lastBoss != null && client.getTickCount() - lastBossTick <= BOSS_CONTEXT_TICKS)
		{
			return lastBoss;
		}
		return "Boss";
	}

	private static boolean shouldNotifyLevel(
		int previous,
		int current,
		SixthDegreeNotificationRules.MilestoneRule rule)
	{
		if (current < rule.minimumLevel || current <= previous)
		{
			return false;
		}
		// From the every-level threshold (90 by default) through 99, every level posts.
		if (rule.levelIntervalOverride > 0 && current >= rule.levelIntervalOverride)
		{
			return true;
		}
		if (rule.levelInterval <= 1)
		{
			return true;
		}
		int remainder = current % rule.levelInterval;
		return remainder == 0 || current - remainder > previous;
	}

	private static String safeSource(String source, String fallback)
	{
		return source == null || source.isBlank() ? fallback : Text.removeTags(source).trim();
	}

	private static String formatGp(long value)
	{
		return String.format(Locale.UK, "%,d gp", value);
	}

	private static String formatNumber(long value)
	{
		return String.format(Locale.UK, "%,d", value);
	}

	private static final class DropPart
	{
		final int itemId;
		final String name;
		final int quantity;
		final long value;

		DropPart(int itemId, String name, int quantity, long value)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.value = value;
		}
	}

	private static final class BossCount
	{
		final String boss;
		final int count;

		BossCount(String boss, int count)
		{
			this.boss = boss;
			this.count = count;
		}
	}
}

