	private void addLootRule(JsonObject rule)
	{
		JPanel panel = card();
		addCardTitle(panel, "VALUABLE / RARE LOOT");
		addCardText(panel, bool(rule, "enabled", false) ? "Enabled ✓" : "Disabled");
		long minimum = longValue(rule, "minimum_value", 0L);
