@Slf4j
@PluginDescriptor(
	name = "Sixth Degree",
	description = "Official Sixth Degree clan companion for events, competitions, LFG and clan notifications"
)
public class SixthDegreePlugin extends Plugin
{
	private static final String CLAN_NAME = "Sixth Degree";
	private static final String CONFIG_GROUP = "sixthdegree";
	private static final int MEMBERSHIP_RECHECK_TICKS = 100;
	private static final long SESSION_RECHECK_MILLIS = TimeUnit.MINUTES.toMillis(10);
	private static final long LOOT_FLUSH_SECONDS = 60L;
	private static final long LEADERBOARD_REFRESH_SECONDS = 30L;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SixthDegreeConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private SixthDegreeLootService lootService;

	@Inject
	private EventBus eventBus;

	@Inject
	private SixthDegreeNotificationCoordinator notificationCoordinator;

	@Inject
	private SixthDegreeApiClient apiClient;

	@Inject
	private SixthDegreeRealtimeClient realtimeClient;

	@Inject
	private SixthDegreeSoundService sounds;

	private final AtomicBoolean authPollInFlight = new AtomicBoolean(false);
	private final AtomicBoolean lootSendInFlight = new AtomicBoolean(false);
	private final AtomicBoolean realtimeConnecting = new AtomicBoolean(false);

	private SixthDegreePanel panel;
	private NavigationButton navigationButton;
	private ScheduledExecutorService scheduler;
	private ScheduledFuture<?> authPollTask;
	private ScheduledFuture<?> lootFlushTask;
	private ScheduledFuture<?> leaderboardRefreshTask;
	private ScheduledFuture<?> realtimeGuardTask;
	private volatile WebSocket realtimeSocket;
	private int membershipTicks;
	private String validatedRsn;
	private boolean sessionValid;
	private long lastSessionCheckMillis;
	private boolean sessionValidationInFlight;
	private String connectionAnnouncedRsn;
	private volatile String pendingAuthRequestId;
	private volatile String pendingAuthRsn;

	@Override
	protected void startUp()
	{
		sounds.start();
		scheduler = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread thread = new Thread(r, "sixth-degree-services");
			thread.setDaemon(true);
			return thread;
		});

		panel = new SixthDegreePanel(
			apiClient,
			message -> clientThread.invokeLater(() ->
			{
				addGameMessage(message);
				if (config.notificationSound())
				{
					sounds.play(SixthDegreeSoundService.Cue.LFG);
				}
			}));
		navigationButton = NavigationButton.builder()
			.tooltip("Sixth Degree")
			.icon(buildSixthDegreeIcon())
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);

		notificationCoordinator.start(apiClient);
		eventBus.register(notificationCoordinator);

		lootFlushTask = scheduler.scheduleAtFixedRate(
			this::flushLootTelemetry,
			LOOT_FLUSH_SECONDS,
			LOOT_FLUSH_SECONDS,
			TimeUnit.SECONDS);
		leaderboardRefreshTask = scheduler.scheduleAtFixedRate(
			() -> SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.refreshLootLeaderboardIfVisible();
					panel.refreshCompetitionIfVisible();
				}
			}),
			LEADERBOARD_REFRESH_SECONDS,
			LEADERBOARD_REFRESH_SECONDS,
			TimeUnit.SECONDS);
		realtimeGuardTask = scheduler.scheduleAtFixedRate(
			() -> clientThread.invokeLater(this::ensureRealtimeConnected),
			10,
			30,
			TimeUnit.SECONDS);

		refreshAccessState();
		log.debug("Sixth Degree started");
	}

	@Override
	protected void shutDown()
	{
		removeLfgForValidatedAccount();
		lootService.sealBatch();
		flushLootTelemetry();
		disconnectRealtime();
		cancelAuthPolling();
		eventBus.unregister(notificationCoordinator);
		notificationCoordinator.stop();
		sounds.stop();
		if (lootFlushTask != null)
		{
			lootFlushTask.cancel(false);
			lootFlushTask = null;
		}
		if (leaderboardRefreshTask != null)
		{
			leaderboardRefreshTask.cancel(false);
			leaderboardRefreshTask = null;
		}
		if (realtimeGuardTask != null)
		{
			realtimeGuardTask.cancel(false);
			realtimeGuardTask = null;
		}
		if (scheduler != null)
		{
			scheduler.shutdownNow();
			scheduler = null;
		}
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		navigationButton = null;
		panel = null;
		validatedRsn = null;
		sessionValid = false;
		membershipTicks = 0;
		connectionAnnouncedRsn = null;
		log.debug("Sixth Degree stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		membershipTicks = 0;
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			removeLfgForValidatedAccount();
			lootService.sealBatch();
			flushLootTelemetry();
			disconnectRealtime();
			notificationCoordinator.deactivate();
			connectionAnnouncedRsn = null;
		}
		refreshAccessState();
	}

	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		if (!event.isGuest())
		{
			refreshAccessState();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		membershipTicks++;
		if (membershipTicks >= MEMBERSHIP_RECHECK_TICKS)
		{
			membershipTicks = 0;
			refreshAccessState();
		}
	}

	@Subscribe(priority = 1)
	public void onNpcLootReceived(NpcLootReceived event)
	{
		if (canSendMemberTelemetry())
		{
			lootService.record(event.getItems());
		}
	}

	@Subscribe(priority = 1)
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (canSendMemberTelemetry())
		{
			lootService.record(event.getItems());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (canSendMemberTelemetry() && event.getType() != LootRecordType.PLAYER)
		{
			lootService.record(event.getItems());
		}
	}

	private boolean canSendMemberTelemetry()
	{
		String rsn = validatedRsn;
		return sessionValid
			&& rsn != null
			&& client.getGameState() == GameState.LOGGED_IN
			&& sameRsn(rsn, currentRsn())
			&& isCurrentAccountInSixthDegree(rsn);
	}

	private void refreshAccessState()
	{
		if (panel == null)
		{
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			panel.showLoggedOut();
			return;
		}

		String rsn = currentRsn();
		if (rsn == null)
		{
			panel.showLoggedOut();
			return;
		}

		if (!isCurrentAccountInSixthDegree(rsn))
		{
			cancelAuthPolling();
			clearTransientValidation();
			panel.showRecruitment(rsn);
			return;
		}

		if (pendingAuthRequestId != null && sameRsn(rsn, pendingAuthRsn))
		{
			panel.showLinking(rsn);
			return;
		}

		String token = loadSessionToken(rsn);
		if (token == null || token.isBlank())
		{
			clearTransientValidation();
			panel.showDiscordLinkRequired(rsn, () -> clientThread.invokeLater(() -> beginDiscordLink(rsn)));
			return;
		}

		long now = System.currentTimeMillis();
		if (sessionValid && sameRsn(rsn, validatedRsn) && now - lastSessionCheckMillis < SESSION_RECHECK_MILLIS)
		{
			showMemberPanel(rsn, token);
			ensureRealtimeConnected();
			return;
		}

		validateSession(rsn, token);
	}

	private void showMemberPanel(String rsn, String token)
	{
		panel.showMemberHome(
			rsn,
			token,
			client.getWorld(),
			config.notifications(),
			config.notificationSound(),
			config.deathScreenshots()
		);
	}

	private void validateSession(String rsn, String token)
	{
		if (sessionValidationInFlight)
		{
			return;
		}
		boolean preserveMemberPanel = sessionValid && sameRsn(rsn, validatedRsn);
		sessionValidationInFlight = true;
		if (!preserveMemberPanel)
		{
			panel.showCheckingAccess(rsn);
		}

		apiClient.getMemberStatus(token).whenComplete((status, throwable) ->
			clientThread.invokeLater(() ->
				handleSessionValidation(rsn, status, throwable, preserveMemberPanel)));
	}

	private void handleSessionValidation(
		String rsn,
		SixthDegreeApiClient.MemberStatus status,
		Throwable throwable,
		boolean preserveMemberPanel)
	{
		sessionValidationInFlight = false;
		if (!isStillCurrentClanAccount(rsn))
		{
			return;
		}

		if (throwable != null)
		{
			Throwable cause = unwrap(throwable);
			if (cause instanceof SixthDegreeApiClient.ApiException)
			{
				int code = ((SixthDegreeApiClient.ApiException) cause).getStatusCode();
				if (code == 401 || code == 403)
				{
					removeSessionToken(rsn);
					clearTransientValidation();
					panel.showDiscordLinkRequired(
						rsn,
						() -> clientThread.invokeLater(() -> beginDiscordLink(rsn)),
						"Your previous Discord authorisation is no longer valid."
					);
					return;
				}
			}

			if (!preserveMemberPanel)
			{
				panel.showConnectionError(rsn, () -> clientThread.invokeLater(this::refreshAccessState));
			}
			return;
		}

		if (status == null || !status.ok || !"member".equalsIgnoreCase(status.access) || !sameRsn(rsn, status.rsn))
		{
			removeSessionToken(rsn);
			clearTransientValidation();
			panel.showDiscordLinkRequired(rsn, () -> clientThread.invokeLater(() -> beginDiscordLink(rsn)));
			return;
		}

		validatedRsn = rsn;
		sessionValid = true;
		lastSessionCheckMillis = System.currentTimeMillis();
		String token = loadSessionToken(rsn);
		if (token != null && !token.isBlank())
		{
			showMemberPanel(rsn, token);
			announceConnectedOnce(rsn);
			ensureRealtimeConnected();
			notificationCoordinator.activate(token);
			flushLootTelemetry();
		}
	}

	private void beginDiscordLink(String rsn)
	{
		if (!isStillCurrentClanAccount(rsn) || pendingAuthRequestId != null)
		{
			return;
		}

		panel.showCheckingAccess(rsn);
		apiClient.startDiscordAuth(rsn).whenComplete((auth, throwable) ->
			clientThread.invokeLater(() -> handleAuthStart(rsn, auth, throwable)));
	}

	private void handleAuthStart(String rsn, SixthDegreeApiClient.AuthStart auth, Throwable throwable)
	{
		if (!isStillCurrentClanAccount(rsn))
		{
			return;
		}
		if (throwable != null || auth == null || auth.request_id == null || auth.authorize_url == null)
		{
			panel.showConnectionError(rsn, () -> clientThread.invokeLater(() -> beginDiscordLink(rsn)));
			return;
		}

		pendingAuthRequestId = auth.request_id;
		pendingAuthRsn = rsn;
		panel.showLinking(rsn);
		SwingUtilities.invokeLater(() -> LinkBrowser.browse(auth.authorize_url));
		startAuthPolling();
	}

	private void startAuthPolling()
	{
		cancelAuthPollingTaskOnly();
		if (scheduler != null && !scheduler.isShutdown())
		{
			authPollTask = scheduler.scheduleAtFixedRate(this::pollDiscordAuth, 2, 2, TimeUnit.SECONDS);
		}
	}

	private void pollDiscordAuth()
	{
		String requestId = pendingAuthRequestId;
		String rsn = pendingAuthRsn;
		if (requestId == null || rsn == null)
		{
			return;
		}
		if (!authPollInFlight.compareAndSet(false, true))
		{
			return;
		}

		apiClient.getDiscordAuthStatus(requestId).whenComplete((status, throwable) ->
		{
			authPollInFlight.set(false);
			clientThread.invokeLater(() -> handleAuthPollResult(rsn, status, throwable));
		});
	}

	private void handleAuthPollResult(String rsn, SixthDegreeApiClient.AuthStatus status, Throwable throwable)
	{
		if (!isStillCurrentClanAccount(rsn))
		{
			cancelAuthPolling();
			return;
		}
		if (throwable != null)
		{
			Throwable cause = unwrap(throwable);
			if (cause instanceof SixthDegreeApiClient.ApiException
				&& ((SixthDegreeApiClient.ApiException) cause).getStatusCode() == 404)
			{
				finishAuthFailure(rsn, "The Discord link expired. Please try again.");
			}
			return;
		}
		if (status == null || status.status == null)
		{
			return;
		}

		switch (status.status.toLowerCase(Locale.ROOT))
		{
			case "approved":
				if (status.session_token == null || status.session_token.isBlank() || !sameRsn(rsn, status.rsn))
				{
					finishAuthFailure(rsn, "Boss Lady could not complete the account link. Please try again.");
					return;
				}
				saveSessionToken(rsn, status.session_token);
				cancelAuthPolling();
				validatedRsn = rsn;
				sessionValid = true;
				lastSessionCheckMillis = System.currentTimeMillis();
				showMemberPanel(rsn, status.session_token);
				announceConnectedOnce(rsn);
				ensureRealtimeConnected();
				notificationCoordinator.activate(status.session_token);
				break;
			case "denied":
				finishAuthFailure(rsn, status.reason == null ? "Discord access was not approved." : status.reason);
				break;
			case "expired":
				finishAuthFailure(rsn, "The Discord link expired. Please try again.");
				break;
			default:
				break;
		}
	}

	private void announceConnectedOnce(String rsn)
	{
		if (sameRsn(connectionAnnouncedRsn, rsn))
		{
			return;
		}
		connectionAnnouncedRsn = rsn;
		addGameMessage("You are connected to Sixth Degree.");
		if (config.notificationSound())
		{
			sounds.play(SixthDegreeSoundService.Cue.LOGIN);
		}
	}

	private void addGameMessage(String message)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		chatMessageManager.queue(
			QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.name("Sixth Degree")
				.runeLiteFormattedMessage("<col=ff69b4>[Sixth Degree] " + message + "</col>")
				.build());
	}

	private void ensureRealtimeConnected()
	{
		if (!canSendMemberTelemetry() || realtimeSocket != null || realtimeConnecting.get())
		{
			return;
		}
		String rsn = validatedRsn;
		String token = rsn == null ? null : loadSessionToken(rsn);
		if (token == null || token.isBlank() || !realtimeConnecting.compareAndSet(false, true))
		{
			return;
		}

		realtimeClient.connect(
			token,
			event -> clientThread.invokeLater(() -> handleRealtimeEvent(event)),
			() ->
			{
				realtimeSocket = null;
				realtimeConnecting.set(false);
			})
			.whenComplete((socket, error) ->
			{
				realtimeConnecting.set(false);
				if (error != null)
				{
					realtimeSocket = null;
					return;
				}
				realtimeSocket = socket;
			});
	}

	private void handleRealtimeEvent(SixthDegreeRealtimeClient.RealtimeEvent event)
	{
		if (event == null || event.type == null || !canSendMemberTelemetry())
		{
			return;
		}
		if ("competition_updated".equalsIgnoreCase(event.type))
		{
			notificationCoordinator.refreshCompetitionState();
			if (panel != null)
			{
				SwingUtilities.invokeLater(panel::refreshCompetitionIfVisible);
			}
			return;
		}
		if ("lfg_posted".equalsIgnoreCase(event.type) && event.entry != null)
		{
			SixthDegreeApiClient.LfgEntry entry = event.entry;
			if (entry.rsn == null || sameRsn(entry.rsn, validatedRsn))
			{
				return;
			}
			if (!config.notifications() && !config.notificationSound())
			{
				return;
			}
			String note = entry.note == null || entry.note.isBlank() ? "a group" : entry.note;
			String line = entry.rsn + " is looking for: " + note + (entry.world > 0 ? " (W" + entry.world + ")" : "");
			if (config.notifications())
			{
				addGameMessage("LFG • " + line);
			}
			if (config.notificationSound())
			{
				sounds.play(SixthDegreeSoundService.Cue.LFG);
			}
		}
	}

	private void disconnectRealtime()
	{
		WebSocket socket = realtimeSocket;
		realtimeSocket = null;
		realtimeConnecting.set(false);
		if (socket != null)
		{
			try
			{
				socket.close(1000, "Sixth Degree session ended");
			}
			catch (Exception ignored)
			{
				// Socket is already gone.
			}
		}
	}

	private void flushLootTelemetry()
	{
		lootService.sealBatch();
		if (!sessionValid || validatedRsn == null || !lootSendInFlight.compareAndSet(false, true))
		{
			return;
		}
		SixthDegreeLootService.Batch batch = lootService.peekBatch();
		if (batch == null)
		{
			lootSendInFlight.set(false);
			return;
		}
		String token = loadSessionToken(validatedRsn);
		if (token == null || token.isBlank())
		{
			lootSendInFlight.set(false);
			return;
		}

		apiClient.postLootBatch(token, batch.id, batch.valueGp, batch.dropCount, batch.recordedAt)
			.whenComplete((response, error) ->
			{
				if (error == null && response != null && response.ok)
				{
					lootService.acknowledge(batch.id);
					SwingUtilities.invokeLater(() ->
					{
						if (panel != null)
						{
							panel.refreshLootLeaderboardIfVisible();
						}
					});
				}
				lootSendInFlight.set(false);
				if (error == null && lootService.peekBatch() != null && scheduler != null && !scheduler.isShutdown())
				{
					scheduler.schedule(this::flushLootTelemetry, 1, TimeUnit.SECONDS);
				}
			});
	}

	private void finishAuthFailure(String rsn, String reason)
	{
		cancelAuthPolling();
		if (isStillCurrentClanAccount(rsn))
		{
			panel.showDiscordLinkRequired(
				rsn,
				() -> clientThread.invokeLater(() -> beginDiscordLink(rsn)),
				reason
			);
		}
	}

	private void removeLfgForValidatedAccount()
	{
		String rsn = validatedRsn;
		if (rsn == null || rsn.isBlank())
		{
			return;
		}
		String token = loadSessionToken(rsn);
		if (token == null || token.isBlank())
		{
			return;
		}
		apiClient.deleteMyLfg(token).exceptionally(error -> null);
	}

	private void cancelAuthPolling()
	{
		cancelAuthPollingTaskOnly();
		pendingAuthRequestId = null;
		pendingAuthRsn = null;
		authPollInFlight.set(false);
	}

	private void cancelAuthPollingTaskOnly()
	{
		if (authPollTask != null)
		{
			authPollTask.cancel(false);
			authPollTask = null;
		}
	}

	private void clearTransientValidation()
	{
		disconnectRealtime();
		notificationCoordinator.deactivate();
		validatedRsn = null;
		sessionValid = false;
		lastSessionCheckMillis = 0;
		sessionValidationInFlight = false;
	}

	private String currentRsn()
	{
		Player localPlayer = client.getLocalPlayer();
		String name = localPlayer == null ? null : localPlayer.getName();
		return name == null || name.isBlank() ? null : name;
	}

	private boolean isCurrentAccountInSixthDegree(String rsn)
	{
		ClanSettings clanSettings = client.getClanSettings();
		return clanSettings != null
			&& CLAN_NAME.equalsIgnoreCase(clanSettings.getName())
			&& clanSettings.findMember(rsn) != null;
	}

	private boolean isStillCurrentClanAccount(String rsn)
	{
		return client.getGameState() == GameState.LOGGED_IN
			&& sameRsn(rsn, currentRsn())
			&& isCurrentAccountInSixthDegree(rsn);
	}

	private static boolean sameRsn(String a, String b)
	{
		return a != null && b != null && normaliseRsn(a).equals(normaliseRsn(b));
	}

	private static String normaliseRsn(String rsn)
	{
		return rsn.trim()
			.replace('_', ' ')
			.replaceAll("\\s+", " ")
			.toLowerCase(Locale.ROOT);
	}

	private String loadSessionToken(String rsn)
	{
		return configManager.getConfiguration(CONFIG_GROUP, sessionKey(rsn));
	}

	private void saveSessionToken(String rsn, String token)
	{
		configManager.setConfiguration(CONFIG_GROUP, sessionKey(rsn), token);
	}

	private void removeSessionToken(String rsn)
	{
		configManager.unsetConfiguration(CONFIG_GROUP, sessionKey(rsn));
	}

	private static String sessionKey(String rsn)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(normaliseRsn(rsn).getBytes(StandardCharsets.UTF_8));
			StringBuilder out = new StringBuilder("session_");
			for (int i = 0; i < 12; i++)
			{
				out.append(String.format("%02x", digest[i]));
			}
			return out.toString();
		}
		catch (Exception e)
		{
			throw new IllegalStateException("Unable to create RuneLite session key", e);
		}
	}

	private static Throwable unwrap(Throwable throwable)
	{
		Throwable current = throwable;
		while (current instanceof CompletionException && current.getCause() != null)
		{
			current = current.getCause();
		}
		return current;
	}

	private static BufferedImage buildSixthDegreeIcon()
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			graphics.setColor(Color.WHITE);
			graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 29));
			graphics.drawString("6", 3, 29);
			graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
			graphics.drawString("°", 22, 11);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	@Provides
	SixthDegreeConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(SixthDegreeConfig.class);
	}
}

package com.sixthdegree;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.OptionalDouble;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Looks up NPC drop probabilities using the DinkPlugin drop-rate dataset served by
 * the Sixth Degree API. Keeping the data behind the clan API means the plugin only
 * communicates with the service already disclosed to members.
 */
@Slf4j
@Singleton
final class SixthDegreeRarityService
{
	private static final Type RAW_TYPE = new TypeToken<Map<String, List<RawDrop>>>() { }.getType();

	private final ItemManager itemManager;
	private final Gson gson;
	private volatile Map<String, List<RareDrop>> dropsBySource = Collections.emptyMap();
	private volatile boolean loaded;

	@Inject
	SixthDegreeRarityService(ItemManager itemManager, Gson gson)
	{
		this.itemManager = itemManager;
		this.gson = gson;
	}

	boolean isLoaded()
	{
		return loaded;
	}

	synchronized boolean load(String json)
	{
		if (json == null || json.isBlank())
		{
			return false;
		}
		try
		{
			Map<String, List<RawDrop>> raw = gson.fromJson(json, RAW_TYPE);
			if (raw == null || raw.isEmpty())
			{
				return false;
			}

			Map<String, List<RareDrop>> parsed = new HashMap<>(raw.size());
			for (Map.Entry<String, List<RawDrop>> entry : raw.entrySet())
			{
				List<RareDrop> transformed = new ArrayList<>();
				if (entry.getValue() != null)
				{
					for (RawDrop drop : entry.getValue())
					{
						transformed.addAll(transform(drop));
					}
				}
				parsed.put(normaliseSource(entry.getKey()), transformed);
			}
			dropsBySource = parsed;
			loaded = true;
			return true;
		}
		catch (Exception ex)
		{
			log.warn("Could not load Sixth Degree NPC rarity data", ex);
			return false;
		}
	}

	boolean qualifies(String source, Collection<ItemStack> items, int oneInX)
	{
		if (!loaded || oneInX <= 0 || source == null || source.isBlank() || items == null)
		{
			return false;
		}
		double threshold = 1.0d / (double) oneInX;
		for (ItemStack item : items)
		{
			if (item == null || item.getId() < 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			OptionalDouble probability = getProbability(source, item.getId(), item.getQuantity());
			if (probability.isPresent() && probability.getAsDouble() <= threshold)
			{
				return true;
			}
		}
		return false;
	}

	OptionalDouble getProbability(String source, int itemId, int quantity)
	{
		List<RareDrop> drops = dropsBySource.get(normaliseSource(source));
		if (drops == null || drops.isEmpty())
		{
			return OptionalDouble.empty();
		}

		ItemComposition composition;
		try
		{
			composition = itemManager.getItemComposition(itemId);
		}
		catch (Exception ex)
		{
			composition = null;
		}

		int canonical = composition != null && composition.getNote() != -1
			? composition.getLinkedNoteId()
			: itemId;
		String itemName = composition == null ? "" : composition.getMembersName();
		Set<Integer> variants = new HashSet<>(
			ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical)));

		double sum = 0.0d;
		boolean found = false;
		for (RareDrop drop : drops)
		{
			if (quantity < drop.minQuantity || quantity > drop.maxQuantity)
			{
				continue;
			}
			boolean itemMatches = drop.itemId == itemId;
			if (!itemMatches && variants.contains(drop.itemId))
			{
				try
				{
					itemMatches = itemName.equals(itemManager.getItemComposition(drop.itemId).getMembersName());
				}
				catch (Exception ignored)
				{
					itemMatches = false;
				}
			}
			if (itemMatches)
			{
				found = true;
				sum += drop.probability;
			}
		}
		return found ? OptionalDouble.of(sum) : OptionalDouble.empty();
	}

	private static Collection<RareDrop> transform(RawDrop raw)
	{
		if (raw == null || raw.denominator <= 0.0d)
		{
			return Collections.emptyList();
		}
		int rolls = raw.rolls == null ? 1 : Math.max(1, raw.rolls);
		int baseQuantity = raw.quantity == null ? 1 : Math.max(1, raw.quantity);
		int minimum = raw.minimum == null ? baseQuantity : Math.max(1, raw.minimum);
		int maximum = raw.maximum == null ? baseQuantity : Math.max(minimum, raw.maximum);
		double probability = 1.0d / raw.denominator;

		List<RareDrop> output = new ArrayList<>(rolls);
		if (rolls == 1)
		{
			output.add(new RareDrop(raw.itemId, minimum, maximum, probability));
			return output;
		}

		for (int successes = 1; successes <= rolls; successes++)
		{
			output.add(new RareDrop(
				raw.itemId,
				minimum * successes,
				maximum * successes,
				binomialProbability(probability, rolls, successes)));
		}
		return output;
	}

	private static double binomialProbability(double probability, int trials, int successes)
	{
		double combinations = 1.0d;
		for (int i = 1; i <= successes; i++)
		{
			combinations *= (double) (trials - (successes - i)) / (double) i;
		}
		return combinations
			* Math.pow(probability, successes)
			* Math.pow(1.0d - probability, trials - successes);
	}

	private static String normaliseSource(String source)
	{
		return source == null ? "" : source.trim().toLowerCase(Locale.ROOT);
	}

	private static final class RareDrop
	{
		final int itemId;
		final int minQuantity;
		final int maxQuantity;
		final double probability;

		RareDrop(int itemId, int minQuantity, int maxQuantity, double probability)
		{
			this.itemId = itemId;
			this.minQuantity = minQuantity;
			this.maxQuantity = maxQuantity;
			this.probability = probability;
		}
	}

	private static final class RawDrop
	{
		@SerializedName("i")
		int itemId;
		@SerializedName("r")
		Integer rolls;
		@SerializedName("d")
		double denominator;
		@SerializedName("q")
		Integer quantity;
		@SerializedName("m")
		Integer minimum;
		@SerializedName("n")
		Integer maximum;
	}
}

package com.sixthdegree;

import com.google.gson.Gson;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

@Singleton
final class SixthDegreeRealtimeClient
{
	private static final String WS_URL = SixthDegreeApiClient.API_BASE.replaceFirst("^https://", "wss://") + "/ws";

	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	SixthDegreeRealtimeClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	CompletableFuture<WebSocket> connect(String sessionToken, Consumer<RealtimeEvent> onEvent, Runnable onClosed)
	{
		CompletableFuture<WebSocket> connected = new CompletableFuture<>();
		Request request = new Request.Builder()
			.url(WS_URL)
			.header("Authorization", "Bearer " + sessionToken)
			.header("User-Agent", "Sixth-Degree-RuneLite/0.5")
			.header("ngrok-skip-browser-warning", "sixth-degree-runelite")
			.build();
		httpClient.newWebSocket(request, new Listener(gson, onEvent, onClosed, connected));
		return connected;
	}

	static final class RealtimeEvent
	{
		String type;
		String rsn;
		long server_time;
		SixthDegreeApiClient.LfgEntry entry;
	}

	private static final class Listener extends WebSocketListener
	{
		private final Gson gson;
		private final Consumer<RealtimeEvent> onEvent;
		private final Runnable onClosed;
		private final CompletableFuture<WebSocket> connected;
		private final AtomicBoolean closed = new AtomicBoolean(false);

		private Listener(
			Gson gson,
			Consumer<RealtimeEvent> onEvent,
			Runnable onClosed,
			CompletableFuture<WebSocket> connected)
		{
			this.gson = gson;
			this.onEvent = onEvent;
			this.onClosed = onClosed;
			this.connected = connected;
		}

		@Override
		public void onOpen(WebSocket webSocket, Response response)
		{
			connected.complete(webSocket);
		}

		@Override
		public void onMessage(WebSocket webSocket, String text)
		{
			try
			{
				RealtimeEvent event = gson.fromJson(text, RealtimeEvent.class);
				if (event != null && event.type != null)
				{
					onEvent.accept(event);
				}
			}
			catch (Exception ignored)
			{
				// Ignore malformed realtime messages; the normal API remains authoritative.
			}
		}

		@Override
		public void onClosed(WebSocket webSocket, int code, String reason)
		{
			notifyClosed();
		}

		@Override
		public void onFailure(WebSocket webSocket, Throwable throwable, Response response)
		{
			connected.completeExceptionally(throwable);
			notifyClosed();
			if (response != null)
			{
				response.close();
			}
		}

		private void notifyClosed()
		{
			if (closed.compareAndSet(false, true))
			{
				onClosed.run();
			}
		}
	}
}

package com.sixthdegree;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.concurrent.CompletableFuture;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;

@Slf4j
@Singleton
final class SixthDegreeScreenshotService
{
	private final DrawManager drawManager;

	@Inject
	SixthDegreeScreenshotService(DrawManager drawManager)
	{
		this.drawManager = drawManager;
	}

	CompletableFuture<byte[]> capturePng()
	{
		CompletableFuture<byte[]> future = new CompletableFuture<>();
		drawManager.requestNextFrameListener(image ->
		{
			final BufferedImage snapshot;
			try
			{
				// DrawManager's frame belongs to RuneLite's render pipeline. Copy it while
				// we're still inside the callback so a later render cannot mutate the image
				// while PNG encoding runs on a background thread.
				snapshot = copyFrame(image);
			}
			catch (Exception e)
			{
				future.completeExceptionally(e);
				return;
			}

			CompletableFuture.runAsync(() ->
			{
				try
				{
					byte[] png = toPng(snapshot);
					log.info(
						"Sixth Degree screenshot captured: {}x{} ({})",
						snapshot.getWidth(),
						snapshot.getHeight(),
						formatBytes(png.length));
					future.complete(png);
				}
				catch (Exception e)
				{
					future.completeExceptionally(e);
				}
			});
		});
		return future;
	}

	private static BufferedImage copyFrame(Image image)
	{
		if (image == null)
		{
			throw new IllegalStateException("RuneLite returned no screenshot frame");
		}
		int width = Math.max(1, image.getWidth(null));
		int height = Math.max(1, image.getHeight(null));
		BufferedImage copy = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = copy.createGraphics();
		try
		{
			graphics.drawImage(image, 0, 0, null);
		}
		finally
		{
			graphics.dispose();
		}
		return copy;
	}

	private static String formatBytes(int bytes)
	{
		if (bytes >= 1024 * 1024)
		{
			return String.format(java.util.Locale.UK, "%.2f MiB", bytes / (1024.0 * 1024.0));
		}
		return Math.max(0, bytes / 1024) + " KiB";
	}

	private static byte[] toPng(BufferedImage buffered) throws Exception
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream(1024 * 512);
		if (!ImageIO.write(buffered, "png", output))
		{
			throw new IllegalStateException("No PNG writer is available");
		}
		return output.toByteArray();
	}
}

package com.sixthdegree;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

@Slf4j
@Singleton
final class SixthDegreeSoundService
{
	enum Cue
	{
		BOTW("botw.wav"),
		COLLECTION_LOG("collection-log.wav"),
		DEATH("death.wav"),
		LFG("lfg.wav"),
		LOGIN("login.wav"),
		PERSONAL_BEST("personal-best.wav"),
		QUEST("quest.wav"),
		SOTW("sotw.wav"),
		WINNER("winner.wav");

		private final String fileName;

		Cue(String fileName)
		{
			this.fileName = fileName;
		}
	}

	private final AudioPlayer audioPlayer;
	private ExecutorService executor;

	@Inject
	SixthDegreeSoundService(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	synchronized void start()
	{
		if (executor != null && !executor.isShutdown())
		{
			return;
		}
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread thread = new Thread(r, "sixth-degree-sounds");
			thread.setDaemon(true);
			return thread;
		});
	}

	synchronized void stop()
	{
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	void play(Cue cue)
	{
		ExecutorService current;
		synchronized (this)
		{
			current = executor;
		}
		if (cue == null || current == null || current.isShutdown())
		{
			return;
		}
		try
		{
			current.execute(() -> playNow(cue));
		}
		catch (RejectedExecutionException ignored)
		{
			// RuneLite is shutting the plugin down.
		}
	}

	static String resourcePath(Cue cue)
	{
		return "/com/sixthdegree/sounds/" + cue.fileName;
	}

	private void playNow(Cue cue)
	{
		try
		{
			audioPlayer.play(SixthDegreeSoundService.class, resourcePath(cue), 0.0f);
		}
		catch (Exception error)
		{
			log.debug("Unable to play Sixth Degree sound {}", cue, error);
		}
	}
}

