	{
		SixthDegreeApiClient api = mock(SixthDegreeApiClient.class);
		when(api.postCompetitionProgress(anyString(), anyString(), eq(7), anyLong(), anyLong(), anyLong(), anyString()))
			.thenReturn(new CompletableFuture<>());
